actor SingleFlight<Value> {
    final class Flight {
        let task: Task<Value, Error>
        init(_ w: @escaping () async throws -> Value) { task = Task { try await w() } }
    }
    private var inflight: [String: Flight] = [:]
    func value(for key: String, _ work: @escaping () async throws -> Value) async throws -> Value {
        if let f = inflight[key] { return try await f.task.value }   // join
        let f = Flight(work); inflight[key] = f          // stored BEFORE any await
        defer { if inflight[key] === f { inflight[key] = nil } }     // forget
        return try await f.task.value
    }
}
